import axios from 'axios';
import { generateSignature } from '../signer/signer';
export async function getAudioDetails(audioIdOrUrl) {
    try {
        // Extraer el ID del audio si se proporciona una URL
        const audioId = audioIdOrUrl.includes('tiktok.com')
            ? audioIdOrUrl.split('/music/')[1]?.split('?')[0]
            : audioIdOrUrl;
        if (!audioId)
            throw new Error('Invalid audio ID or URL');
        const url = `https://www.tiktok.com/music/${audioId}`;
        const sig = await generateSignature(url);
        const res = await axios.get(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
                'Referer': 'https://www.tiktok.com/',
                'x-tt-params': sig,
            },
        });
        const match = res.data.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application\/json">(.+?)<\/script>/);
        if (!match)
            throw new Error('Audio data not found');
        const json = JSON.parse(match[1]);
        const musicInfo = json.props?.pageProps?.musicInfo;
        if (!musicInfo)
            throw new Error('Audio details not found');
        return {
            id: musicInfo.id || '',
            title: musicInfo.title || '',
            videoCount: musicInfo.stats?.videoCount || 0,
            author: musicInfo.authorName || '',
        };
    }
    catch (error) {
        throw new Error(`Failed to fetch audio details: ${error.message}`);
    }
}
